# OpenSubdiv (OPENSUBDIV) – CPU + TBB only (Blender evaluates on GPU via its own module).
build() {
  unpack OPENSUBDIV
  cmake_build -DNO_LIB=OFF -DNO_EXAMPLES=ON -DNO_TUTORIALS=ON -DNO_REGRESSION=ON \
    -DNO_PTEX=ON -DNO_DOC=ON -DNO_OMP=ON -DNO_TBB=OFF -DNO_CUDA=ON -DNO_OPENCL=ON \
    -DNO_CLEW=ON -DNO_OPENGL=ON -DNO_METAL=ON -DNO_DX=ON -DNO_TESTS=ON -DNO_GLTESTS=ON \
    -DNO_GLEW=ON -DNO_GLFW=ON -DNO_GLFW_X11=ON -DNO_MACOS_FRAMEWORK=ON \
    -DTBB_DIR="$LIBDIR/tbb/lib/cmake/TBB"
  rm -f "${PREFIX:?}"/lib/*.so*
}
